sketches.source:
setcpm(60/4)

// Two bars of a 5 Hz binaural beat: each ear hears a steady tone, and the beat forms between them
binaural: note("a2").s("sine").binaural(5).mask("<1 1 0 0>")
  .attack(.5).sustain(1).release(.5).gain(.3)

// Two bars of the same rate as plain amplitude pulsing, audible on speakers too
pulse: note("a2").s("sine").isochronic(5).isodepth(.6).mask("<0 0 1 1>")
  .attack(.5).sustain(1).release(.5).gain(.3)

// A quiet pad that never changes, for reference
pad: note("[a3,c#4,e4]").slow(4).s("triangle").timbre("soft")
  .attack(2).sustain(1).release(3).lpf(1200).room(.6).gain(.12)

setcpm(50/4)

// earsh raises the right ear and lowers the left by half the value each
// 2 cents beats slowly; 30 cents widens into a chorus
drone: note("[d2,a2]").s("sawtooth").earsh("<2 2 6 6 12 12 30 30>")
  .lpf(700).attack(1.5).sustain(1).release(1.5).gain(.22)

// A plain sine, the same in both ears, as a fixed point
centre: note("d3").s("sine").attack(1).sustain(1).release(1).gain(.12)

// A bell marks each new setting
bell: note("<a4 ~>").s("sine").fm(2).fmh(2.76)
  .decay(3).sustain(0).release(3).room(.6).gain(.1)

setcpm(80/4)

// Under about 0.7 ms, a delay between the ears moves the sound sideways
// Negative values delay the right ear, so the pluck leans left; positive values lean right
pluck: n("0 2 4 7 4 2 0 -1").scale("E:minor").s("triangle").timbre("bright")
  .itd(sine.range(-.6, .6).slow(4))
  .decay(.25).sustain(0).release(.3).gain(.3)

// From about 1 to 30 ms the sound stays on the leading side but grows wider
pad: note("<[e3,g3,b3] [c3,e3,g3]>").s("sawtooth").unison(2).detune(.1)
  .itd("<1 1 8 8 20 20 1 1>").lpf(1400)
  .attack(.5).sustain(1).release(1).gain(.14)

// A centred bass, with no delay at all
bass: note("<e2 c2>").s("sine").attack(.2).sustain(.8).release(.5).gain(.3)

setcpm(50/4)

// 0 degrees: centred. 90: looser. 180: diffuse and around the head
// Try it on speakers: the 180-degree bar almost disappears
drone: note("[c2,g2]").s("triangle").iphase("<0 90 180 90>")
  .attack(1).sustain(1).release(1).gain(.3)

// A high sine follows the same phase steps, one bar later
high: note("g4").s("sine").iphase("<90 0 90 180>")
  .attack(1).sustain(1).release(1).gain(.08)

// A plain click at the start of each bar, always centred
click: s("tick ~ ~ ~").gain(.12)

setcpm(40/4)

// icorr 1: the same noise in both ears, a point in the middle
// icorr near 0: unrelated noise in each ear, wide and all around
noise: s("pink").icorr("<1 .7 .4 .1>").lpf(3000)
  .attack(.3).sustain(1).release(.3).gain(.18)

// A soft click at the start of each step
click: s("tick ~ ~ ~").gain(.12)

setcpm(60/4)

// The same noise feeds both ears, but one ear's noise is phase-shifted in a narrow band
// Neither ear alone hears a tone; together they hear a faint pitch at that band
tune: s("white*4").dichotic("<[440 523 659 523] [392 494 587 494] [349 440 523 440] [392 494 587 784]>")
  .dichoticq(30).attack(.02).sustain(1).release(.05).gain(.16)

// A quiet hint: the first phrase on a sine, once every four bars
hint: note("<[a4 c5 e5 c5] ~ ~ ~>").s("sine")
  .decay(.3).sustain(.3).release(.2).gain(.1)

setcpm(96/4)

// earsplit("harmonics") alternates the partials between the ears: each ear hears a thinner tone
pad: note("<[a2,e3,a3] [f2,c3,f3] [c3,g3,c4] [g2,d3,g3]>").s("sawtooth").earsplit("harmonics")
  .attack(.4).sustain(1).release(1).lpf(2400).gain(.16)

// earsplit("bands") splits the lows and highs between the ears at splitfreq; it works on any sound
drums: s("bd ~ [~ bd] ~, ~ sd ~ sd, hh*8").earsplit("bands").splitfreq(900).gain(.5)

// A plain centred bass
bass: note("<a1 f1 c2 g1>").s("sine").attack(.05).sustain(.7).release(.3).gain(.35)

setcpm(72/4)

// A low-pass on each ear alone, sweeping in opposite directions
// The level stays the same; only the brightness wanders between the ears
arp: n("0 2 4 6 7 6 4 2").scale("D:dorian").s("sawtooth")
  .lcutoff(saw.range(400, 5000).slow(8)).rcutoff(isaw.range(400, 5000).slow(8))
  .decay(.2).sustain(.2).release(.2).gain(.18)

// A high-pass on the right ear only: the pad sounds fuller on the left
pad: note("<[d3,f3,a3,c4] [g2,b2,d3,f3]>").slow(2).s("triangle")
  .rhcutoff(1200).attack(1).sustain(1).release(2).room(.5).gain(.16)

setcpm(50/4)

// irate rotates the interaural phase, in turns per second
// All rates stay below 3 Hz, so no pulse warning is needed
drone: note("[e2,b2]").s("sine").irate("<.25 .5 1 2>")
  .attack(1).sustain(1).release(1).gain(.3)

// A still pad above, the same in both ears
pad: note("[e3,g#3,b3]").slow(4).s("triangle").timbre("soft")
  .attack(2).sustain(1).release(3).lpf(1000).room(.6).gain(.12)

// A bell at each change of rate
bell: note("b4").s("sine").fm(2).fmh(2.76)
  .decay(3).sustain(0).release(3).room(.6).gain(.1)
